demo.code:
var tl=G.computeTimeline(DATA.notes, DATA.tempo);
assert(tl.length>0,'timeline non-empty');
assert(Math.abs(tl[0].start)<1e-9,'first event starts at t=0');
var last=tl[tl.length-1];
var totalBeats=DATA.notes.reduce(function(a,ev){return a+ev[1];},0);
var expect=totalBeats*60/DATA.tempo;
assert(Math.abs((last.start+last.dur)-expect)<1e-6,'duration math exact: '+expect.toFixed(4)+'s');
for(var i=1;i<tl.length;i++)assert(tl[i].start>=tl[i-1].start-1e-9,'starts monotonic');
var bad=tl.filter(function(e){return !(e.freq>20&&e.freq<5000);});
assert(bad.length===0,'all frequencies in audible range');
var poly=tl.filter(function(e,i,a){return i>0&&Math.abs(e.start-a[i-1].start)<1e-9;}).length;
log('events='+tl.length+' total='+expect.toFixed(3)+'s range='+tl[0].freq.toFixed(1)+'-'+last.freq.toFixed(1)+'Hz'+(poly?(' polyphonic-starts='+poly):''));

